//! AOT QuickJS bytecode registry.
//!
//! Generated by `cargo run --bin pir-gen-bytecode --features extensions`.
//! Two blob sets exist:
//!
//! * `assets/bytecode/*.qc` — script-boot shims evaluated per runtime from a
//!   standalone blob: the host prelude plus the two assembled Node-compat
//!   boot bundles (`globals`/`node_modules_bootstrap`, whose text is generated
//!   from many shims and is therefore not a single file-backed `Shim`).
//! * `assets/bytecode/v/*.qc` — every virtual module the loader can resolve,
//!   compiled under its **canonical** name. QuickJS keys its module cache by
//!   the resolved name, so the name inside the bytecode must match what the
//!   resolver returns; otherwise every import would create a fresh instance.
//!
//! Regenerate whenever a shim source changes or the engine is upgraded: the
//! guard records the payload length and SHA-256, and a stale blob is rejected
//! rather than loaded.
//!
//! Each blob: 52-byte guard header + QuickJS module bytecode payload.

/// Guard header length: magic(8) + format_version(4) + payload_len(4) +
/// flags(4) + sha256(32).
pub const HEADER_LEN: usize = 52;
pub const MAGIC: &[u8; 8] = b"PIRQCJS\0";
pub const FORMAT_VERSION: u32 = 1;

/// Number of boot shims successfully evaluated from precompiled bytecode in
/// this process. Test/diagnostic hook: the counter is incremented only on the
/// AOT path, never on the source fallback, so a test can pin that a runtime
/// boot actually took the bytecode path.
static AOT_LOADS: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

pub fn aot_loads() -> usize {
    AOT_LOADS.load(std::sync::atomic::Ordering::Relaxed)
}

/// Record one successful precompiled-shim evaluation (called by the runtime).
pub(crate) fn note_aot_load() {
    AOT_LOADS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
}

/// Look up precompiled bytecode for a boot shim by its source file name.
/// The two generated boot bundles are keyed by the synthetic names in
/// [`super::node_shims::GLOBALS_BUNDLE`]/[`super::node_shims::NODE_MODULES_BOOTSTRAP_BUNDLE`].
pub fn bytecode_for(name: &str) -> Option<&'static [u8]> {
    Some(match name {
        "prelude.js.txt" => include_bytes!("../../../assets/bytecode/prelude.js.txt.qc"),
        "node_globals.js.txt" => {
            include_bytes!("../../../assets/bytecode/node_globals.js.txt.qc")
        }
        "node_modules_bootstrap.js.txt" => {
            include_bytes!("../../../assets/bytecode/node_modules_bootstrap.js.txt.qc")
        }
        _ => return None,
    })
}

/// File stem for a canonical module name's blob (`@node/fs/promises` ->
/// `at-node-fs-promises`). Kept in lockstep with `pir-gen-bytecode`.
pub fn blob_stem(canonical: &str) -> String {
    let mut out = String::with_capacity(canonical.len());
    for ch in canonical.chars() {
        match ch {
            '@' => out.push_str("at-"),
            '/' | ':' => out.push('-'),
            c if c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-') => out.push(c),
            _ => out.push('-'),
        }
    }
    out
}

