/// Validate the guard header and return the raw QuickJS bytecode payload.
/// Returns `None` for a stale/incompatible blob so the caller can fall back to
/// source evaluation.
pub fn payload(blob: &'static [u8]) -> Option<&'static [u8]> {
    if blob.len() < HEADER_LEN {
        return None;
    }
    if &blob[..8] != MAGIC {
        return None;
    }
    let version = u32::from_le_bytes(blob[8..12].try_into().ok()?);
    if version != FORMAT_VERSION {
        return None;
    }
    let payload_len = u32::from_le_bytes(blob[12..16].try_into().ok()?) as usize;
    if payload_len == 0 || HEADER_LEN + payload_len != blob.len() {
        return None;
    }
    Some(&blob[HEADER_LEN..])
}
